    for line in path.read_text(errors="ignore").splitlines():
        if ":" in line:
            k, v = line.split(":", 1)
            d[k.strip().lower()] = v.strip()
    return d

def stamps_incidence(rg):
    x = (
        se * se
        - re * re
        - rg * rg
    ) / (
        2.0 * re * rg
    )

    return np.degrees(
        np.arccos(
            np.clip(x, -1.0, 1.0)
        )
    )

def read_par(path):

    d = {}

    for line in path.read_text(
        errors="ignore"
    ).splitlines():

        if ":" not in line:
            continue

        k, v = line.split(
            ":",
            1,
        )

        d[k.strip().lower()] = v.strip()

    return d

def scalar(d, key):

    return float(
        NUM_RE.findall(
            d[key]
        )[0]
    )

def vec3(d, key):

    x = NUM_RE.findall(
        d[key]
    )

    return np.array(
        [
            float(x[0]),
            float(x[1]),
            float(x[2]),
        ],
        dtype=np.float64,
    )

