if gamma_file.is_file():

    gamma = np.fromfile(
        gamma_file,
        dtype=">f4",
    ).astype(
        np.float64
    )


    if gamma.size != N:
        raise RuntimeError(
            "GAMMA truth size mismatch"
        )


    m = (
        valid
        &
        np.isfinite(gamma)
        &
        (gamma > 0)
        &
        (gamma < np.pi/2)
    )


    diff = np.degrees(
        inc[m].astype(
            np.float64
        )
        -
        gamma[m]
    )


    ad = np.abs(
        diff
    )


    rms = float(
        np.sqrt(
            np.mean(
                diff
                *
                diff
            )
        )
    )


    p99 = float(
        np.percentile(
            ad,
            99,
        )
    )


    max_abs = float(
        np.max(
            ad
        )
    )


    print()
    print(
        "FAST vs GAMMA inc_flg=1"
    )

    print(
        "RMS deg                  :",
        f"{rms:.9f}",
    )

    print(
        "p99 |diff| deg           :",
        f"{p99:.9f}",
    )

    print(
        "max |diff| deg           :",
        f"{max_abs:.9f}",
    )


    if (
        rms <= 0.002
        and
        p99 <= 0.005
        and
        max_abs <= 0.02
    ):

        truth_status = (
            "PASS_STRONG"
        )

    else:

        raise RuntimeError(
            "FAST incidence failed GAMMA regression"
        )
